/**
 * Tiny i18n layer (no runtime deps).
 *
 * - One flat strings file per locale: zh-Hant.json (source), en.json, zh-Hans.json.
 *   zh-Hans.json is generated by `npm run i18n` (opencc-js hk→cn + hand-written
 *   standard-written-Chinese overrides in zh-Hans.overrides.json).
 * - `t(key, vars)` works anywhere (components, game/content builders). The provider
 *   re-mounts the app on locale change, so module-level content getters re-read
 *   the active locale.
 */
import { createContext, Fragment, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from 'react'
import en from './en.json'
import zhHans from './zh-Hans.json'
import zhHant from './zh-Hant.json'

export type Locale = 'zh-Hant' | 'zh-Hans' | 'en'
export type MessageKey = keyof typeof zhHant
type Messages = Record<MessageKey, string>

export const LOCALES: Locale[] = ['en', 'zh-Hant', 'zh-Hans']
export const LOCALE_STORAGE_KEY = 'va-nexus:locale:v1'

const MESSAGES: Record<Locale, Partial<Messages>> = {
  'zh-Hant': zhHant as Messages,
  'zh-Hans': zhHans as Partial<Messages>,
  en: en as Partial<Messages>,
}

/** BCP-47 tag for <html lang> */
export const HTML_LANG: Record<Locale, string> = { 'zh-Hant': 'zh-Hant-HK', 'zh-Hans': 'zh-Hans-CN', en: 'en' }
/** Web Speech voice language */
export const SPEECH_LANG: Record<Locale, string> = { 'zh-Hant': 'zh-HK', 'zh-Hans': 'zh-CN', en: 'en-GB' }
/** Intl date/number formatting locale */
export const INTL_LOCALE: Record<Locale, string> = { 'zh-Hant': 'zh-HK', 'zh-Hans': 'zh-CN', en: 'en-HK' }
/** Short switcher labels */
export const LOCALE_SHORT: Record<Locale, string> = { en: 'EN', 'zh-Hant': '繁', 'zh-Hans': '简' }
export const LOCALE_NAME: Record<Locale, string> = { en: 'English', 'zh-Hant': '繁體中文', 'zh-Hans': '简体中文' }

function isLocale(v: unknown): v is Locale {
  return v === 'zh-Hant' || v === 'zh-Hans' || v === 'en'
}

/** navigator.language → locale: zh-HK/zh-TW/zh-MO/zh-Hant → 繁, zh-CN/zh-SG/zh-Hans/zh → 简, else English. */
export function localeFromLanguage(lang: string | undefined | null): Locale {
  const l = (lang ?? '').toLowerCase()
  if (!l.startsWith('zh') && !l.startsWith('yue')) return 'en'
  if (l.startsWith('yue') || /hant|-hk|-tw|-mo/.test(l)) return 'zh-Hant'
  return 'zh-Hans'
}

function detectLocale(): Locale {
  try {
    const saved = localStorage.getItem(LOCALE_STORAGE_KEY)
    if (isLocale(saved)) return saved
  } catch {
    /* ignore */
  }
  if (typeof navigator === 'undefined') return 'zh-Hant'
  return localeFromLanguage(navigator.languages?.[0] ?? navigator.language)
}

let current: Locale = detectLocale()

export function getLocale(): Locale {
  return current
}

function applyHtmlLang(l: Locale) {
  if (typeof document !== 'undefined') document.documentElement.lang = HTML_LANG[l]
}
applyHtmlLang(current)

export type Vars = Record<string, string | number | null | undefined>

/** Translate with {name} interpolation. Missing keys fall back to zh-Hant, then the key. */
export function t(key: MessageKey, vars?: Vars): string {
  const raw = MESSAGES[current][key] ?? MESSAGES['zh-Hant'][key] ?? key
  if (!vars) return raw
  return raw.replace(/\{(\w+)\}/g, (m, k: string) => (k in vars ? String(vars[k] ?? '') : m))
}

/** List joiner for the active locale (、 vs , ) */
export function joinList(items: string[]): string {
  return items.join(current === 'en' ? ', ' : '、')
}

/** Memoise a builder per locale (for module-level content derived from JSON + strings). */
export function perLocale<T>(build: (l: Locale) => T): () => T {
  const cache = new Map<Locale, T>()
  return () => {
    const l = current
    let v = cache.get(l)
    if (v === undefined) {
      v = build(l)
      cache.set(l, v)
    }
    return v
  }
}

type Ctx = { locale: Locale; setLocale: (l: Locale) => void; t: typeof t }
const LocaleContext = createContext<Ctx | null>(null)

export function LocaleProvider({ children }: { children: ReactNode }) {
  const [locale, setState] = useState<Locale>(current)
  const setLocale = useCallback((l: Locale) => {
    if (!isLocale(l)) return
    current = l
    try {
      localStorage.setItem(LOCALE_STORAGE_KEY, l)
    } catch {
      /* ignore */
    }
    applyHtmlLang(l)
    setState(l)
  }, [])
  useEffect(() => applyHtmlLang(locale), [locale])
  // keep module-level `current` in sync even if state was restored by React
  current = locale
  const value = useMemo<Ctx>(() => ({ locale, setLocale, t }), [locale, setLocale])
  return (
    <LocaleContext.Provider value={value}>
      {/* re-mount on change so per-locale content getters + local copies refresh (state lives in localStorage) */}
      <Fragment key={locale}>{children}</Fragment>
    </LocaleContext.Provider>
  )
}

export function useT(): Ctx {
  const ctx = useContext(LocaleContext)
  if (!ctx) throw new Error('useT must be used within LocaleProvider')
  return ctx
}
